#include <bits/stdc++.h>
using namespace std;
class Solution {public:int minimumOperations(string num){int n=num.size(),ans=n;for(string end:vector<string>{"00","25","50","75"}){int j=n-1;while(j>=0&&num[j]!=end[1])--j;if(j<0)continue;int i=j-1;while(i>=0&&num[i]!=end[0])--i;if(i>=0)ans=min(ans,n-i-2);}if(num.find('0')!=string::npos)ans=min(ans,n-1);return ans;}};
